input.script:
export const meta = {
  name: 'multi-agent-demo',
  description: 'Spawn 5 agents doing different tasks with data sharing',
  phases: [
    { title: 'Gather', detail: '3 agents collect info independently' },
    { title: 'Process', detail: '1 agent synthesizes gathered data' },
    { title: 'Report', detail: '1 agent creates final summary' }
  ]
}

phase('Gather')
const researchResult = await agent('Research the history and philosophy of naming things. What are the most interesting naming conventions across different domains? Report back 2-3 fascinating findings.', {
  label: 'Research Agent — History',
  phase: 'Gather'
})

const designResult = await agent('Brainstorm 5 creative code names for a time-tracking app. Each should be memorable, short, and relate to productivity or time. Explain the reasoning.', {
  label: 'Design Agent — Naming',
  phase: 'Gather'
})

const analyticsResult = await agent('Analyze what makes a good software agent name memorable. Look for patterns in successful names (e.g., Figma, Vercel, Stripe). List 4 key principles.', {
  label: 'Analytics Agent — Patterns',
  phase: 'Gather'
})

phase('Process')
const synthesisResult = await agent(`You are synthesizing insights from three specialist agents:

RESEARCH FINDINGS:
${researchResult}

CREATIVE NAMING SUGGESTIONS:
${designResult}

NAMING PRINCIPLES DISCOVERED:
${analyticsResult}

Your task: Combine these three perspectives into a cohesive framework for naming developer tools. What's the unified approach? Create a 3-step formula.`, {
  label: 'Synthesis Agent — Strategy',
  phase: 'Process'
})

phase('Report')
const finalReport = await agent(`Create an executive summary based on this synthesis:

${synthesisResult}

Format it as: KEY INSIGHT + 3 ACTIONABLE RECOMMENDATIONS for naming the next big dev tool.`, {
  label: 'Report Agent — Executive',
  phase: 'Report'
})

return {
  research: researchResult,
  design: designResult,
  analytics: analyticsResult,
  synthesis: synthesisResult,
  finalReport: finalReport
}
